import{_ as r,C as i,o as a,c as l,a2 as s,j as t,a as o,E as c}from"./chunks/framework.D66Xq0Kv.js";const g="/assets/permissions-page.VAGjU8Ew.png",p="/assets/permissions-add.BfVSMrc4.png",d="/assets/permissions-members.B3nW0Xp6.png",h="/assets/create-local.J9QXbqN_.png",C=JSON.parse('{"title":"Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"permissions.md","filePath":"permissions.md"}'),m={name:"permissions.md"},u={id:"creating-a-local-account",tabindex:"-1"};function v(f,e,y,w,b,A){const n=i("Badge");return a(),l("div",null,[e[3]||(e[3]=s('<h1 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h1><p>Permissions control who can see, search, and change assets and templates.</p><p>Every new instance starts locked down: only Elevator SuperAdmins have access until you grant permissions to others.</p><p>A permission has three parts:</p><ul><li><strong>A group</strong>: the people it applies to, such as &quot;Authenticated Users&quot; or a list of specific people.</li><li><strong>A level</strong>: what those people can do, such as &quot;Search and Browse&quot; or &quot;Add Assets to Instance&quot;.</li><li><strong>A scope</strong>: where it applies, either the whole instance (all collections) or a single collection.</li></ul><p>Instance administrators manage instance and collection permissions on the <strong>Permissions</strong> page. Drawer owners share their drawers separately, from the drawer itself. See <a href="/using-drawers.html#drawer-permissions">Drawer Permissions</a>.</p><h2 id="permission-levels" tabindex="-1">Permission Levels <a class="header-anchor" href="#permission-levels" aria-label="Permalink to &quot;Permission Levels&quot;">​</a></h2><p>Each level includes everything the levels above it in this list allow.</p><table tabindex="0"><thead><tr><th>Rank</th><th>Level</th><th>What it allows</th></tr></thead><tbody><tr><td>0</td><td>No Permissions</td><td>Nothing. The user sees a &quot;no permission&quot; message when they visit the instance.</td></tr><tr><td>1</td><td>Search and Browse</td><td>Search and browse assets and see thumbnails, but not larger versions of files.</td></tr><tr><td>2</td><td>View Derivatives (Group 1)</td><td>View the display versions of files in File Handler Group 1. See <a href="/file-groups.html">File Handler Groups</a>.</td></tr><tr><td>3</td><td>View Derivatives (Groups 1 &amp; 2)</td><td>View the display versions of files in File Handler Groups 1 and 2.</td></tr><tr><td>4</td><td>Create/Edit Drawers</td><td>Create drawers, add assets to them, and share them.</td></tr><tr><td>5</td><td>Download Originals</td><td>Download the original uploaded files.</td></tr><tr><td>6</td><td>Add Assets to Instance</td><td>Add new assets and edit existing ones.</td></tr><tr><td>7</td><td>Edit Templates</td><td>Create, edit, duplicate, reindex, and delete templates. This level does not include instance settings, permissions, or collections.</td></tr><tr><td>8</td><td>Administer Instance</td><td>Full control of the instance, including settings, permissions, collections, and templates.</td></tr></tbody></table><p><strong>Edit Templates</strong> and <strong>Administer Instance</strong> only take effect when granted on the whole instance. Granted on a single collection, either one allows the same as <strong>Add Assets to Instance</strong> in that collection.</p><p>When someone belongs to more than one group, they get the <strong>highest permission level</strong> any of their groups grants.</p><div class="info custom-block"><p class="custom-block-title">EXAMPLE</p><p>User is in 3 groups:</p><ul><li><em>Authenticated Users</em> with permission to <strong>Search and Browse (Level 1)</strong></li><li><em>Grad Students</em> with permission to <strong>Download Originals (Level 5)</strong></li><li><em>Library Staff</em> with permission to <strong>Add Assets to Instance (Level 6)</strong></li></ul><p>Their <strong>effective permission</strong> is the highest level: <strong>Add Assets to Instance (Level 6)</strong></p></div><h2 id="instance-and-collection-permissions" tabindex="-1">Instance and Collection Permissions <a class="header-anchor" href="#instance-and-collection-permissions" aria-label="Permalink to &quot;Instance and Collection Permissions&quot;">​</a></h2><p>A permission&#39;s scope is either <strong>Instance</strong> or <strong>Collection</strong>.</p><ul><li><strong>Instance</strong> permissions apply to every collection in the instance.</li><li><strong>Collection</strong> permissions apply to one collection and every collection nested inside it.</li></ul><p>A collection permission can raise a group&#39;s access to the assets in that collection, but it can&#39;t lower it.</p><div class="info custom-block"><p class="custom-block-title">EXAMPLE</p><p>User has these permissions:</p><ul><li><em>Authenticated Users</em> can <strong>Search and Browse (Level 1)</strong> on the <strong>Instance</strong> (all collections).</li><li><em>Research Group</em> can <strong>Add Assets to Instance (Level 6)</strong> on the <strong>Core Samples</strong> collection.</li><li><em>Grad Students</em> can <strong>Create/Edit Drawers (Level 4)</strong> on the <strong>Core Samples</strong> collection.</li></ul><p>Their effective permission on Core Samples is <strong>Add Assets to Instance (Level 6)</strong>, which includes creating and editing drawers. In every other collection, they can only search and browse.</p></div><h2 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h2><p>A group defines who a permission applies to.</p><p>Every instance offers these group types:</p><ul><li><strong>All</strong>: everyone, including visitors who haven&#39;t signed in.</li><li><strong>Authenticated Users</strong>: anyone signed in, by any login method.</li><li><strong>Centrally Authenticated Users</strong>: anyone signed in through your institution&#39;s single sign-on.</li><li><strong>Specific People</strong>: people you choose by name, email, or username.</li></ul><p>Your instance may offer more types, depending on how your institution connects to Elevator. At the University of Minnesota, these include Unit, Job Code, Class Number, Dept/Course Number, Student Status, and Employee Type. Elevator may suggest values based on your own account, such as the courses you teach.</p><h2 id="managing-permissions" tabindex="-1">Managing Permissions <a class="header-anchor" href="#managing-permissions" aria-label="Permalink to &quot;Managing Permissions&quot;">​</a></h2><p>Open the <strong>Admin</strong> menu and choose <strong>Instance Permissions</strong>, or choose <strong>Permissions</strong> in the sidebar on any admin page. Only instance administrators can open this page.</p><p><img src="'+g+'" alt="The Permissions page, with the Permissions table above the Groups table"></p><p>The page has two tables:</p><ul><li><strong>Permissions</strong> lists every permission in the instance: its scope, collection, group, and level.</li><li><strong>Groups</strong> lists every group in the instance and how many permissions it holds. A group with <strong>None</strong> holds no permissions yet.</li></ul><p>To narrow the Permissions table, choose a collection from the <strong>All Collections</strong> menu, or type in <strong>Search permissions</strong>. Choosing a collection renames the page after it, such as &quot;Core Samples Permissions&quot;. Click <strong>Reset</strong> to show every collection again.</p><p>You can also open one collection&#39;s permissions from the <strong>Collections</strong> page: choose <strong>Permissions</strong> from that collection&#39;s <strong>⋮</strong> menu.</p><h3 id="granting-a-permission" tabindex="-1">Granting a Permission <a class="header-anchor" href="#granting-a-permission" aria-label="Permalink to &quot;Granting a Permission&quot;">​</a></h3><ol><li>Click <strong>Create Permission</strong>.</li><li>In <strong>Group</strong>, start typing a group&#39;s name and choose it from the list. To make a new group, type its name, choose <strong>Create group &quot;…&quot;</strong>, and then choose its <strong>Group Type</strong>.</li><li>Choose a <strong>Permission</strong> level.</li><li>Choose a <strong>Scope</strong>: Instance or Collection. For a collection, choose it from the <strong>Collection</strong> menu. If you filtered the table to a collection, it&#39;s already chosen.</li><li>Click <strong>Create</strong>.</li></ol><p><img src="'+p+'" alt="The Create Permission form, granting Library Staff the Download Originals permission on the Core Samples collection"></p><p>A group can hold only one permission level on the instance and one on each collection. If the group already has a level where you&#39;re granting one, Elevator warns you that saving will replace it.</p><p>When you create a new Specific People group, or a new group of one of your institution&#39;s types, Elevator opens it in the table so you can add its first members or entries.</p><h3 id="creating-a-group" tabindex="-1">Creating a Group <a class="header-anchor" href="#creating-a-group" aria-label="Permalink to &quot;Creating a Group&quot;">​</a></h3><p>To create a group before you decide its permissions, click <strong>Create Group</strong> above the Groups table. Choose a <strong>Group Type</strong>, enter a <strong>Group Name</strong>, and click <strong>Create</strong>. The new group holds no permissions. To give it one, choose <strong>Add Permission</strong> from its <strong>⋮</strong> menu.</p><h3 id="adding-people-to-a-group" tabindex="-1">Adding People to a Group <a class="header-anchor" href="#adding-people-to-a-group" aria-label="Permalink to &quot;Adding People to a Group&quot;">​</a></h3><p>Click the arrow at the start of a row, in either table, to expand its group.</p><p><img src="'+d+'" alt="An expanded Specific People group, listing its two members and an Add Member button"></p><ul><li>For a <strong>Specific People</strong> group, click <strong>Add Member</strong> and type a name, email, or username. If the person has never signed in to Elevator, choose <strong>Provision and add remote user</strong> to add them by username. To remove someone, click the trash icon on their row.</li><li>For other group types, click <strong>Add Entry</strong> and choose a suggested value, or type your own and choose <strong>Use &quot;…&quot;</strong>. To change an entry, click its pencil icon. To remove one, click its trash icon.</li></ul><p><strong>All</strong>, <strong>Authenticated Users</strong>, and <strong>Centrally Authenticated Users</strong> include everyone who matches, so they have no members to manage.</p><h3 id="changing-or-removing-a-permission" tabindex="-1">Changing or Removing a Permission <a class="header-anchor" href="#changing-or-removing-a-permission" aria-label="Permalink to &quot;Changing or Removing a Permission&quot;">​</a></h3><p>Each row in the <strong>Permissions</strong> table has a <strong>⋮</strong> menu:</p><ul><li><strong>Edit Group</strong> changes the group&#39;s name, and the level of this permission.</li><li><strong>Remove Permission</strong> removes this one permission. The group and its members remain.</li><li><strong>Delete Group</strong> deletes the group and every permission it holds, on the instance and on every collection.</li></ul><p>Each row in the <strong>Groups</strong> table has a <strong>⋮</strong> menu:</p><ul><li><strong>Edit Group</strong> changes the group&#39;s name.</li><li><strong>Add Permission</strong> grants this group a permission.</li><li><strong>Delete Group</strong> works the same as in the Permissions table.</li></ul><p>A group&#39;s type can&#39;t be changed after it&#39;s created. Removing a permission and deleting a group can&#39;t be undone.</p>',47)),t("h2",u,[e[0]||(e[0]=o("Creating a Local Account ",-1)),c(n,{type:"info",text:"Classic UI"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#creating-a-local-account","aria-label":'Permalink to "Creating a Local Account <Badge type="info" text="Classic UI" />"'},"​",-1))]),e[4]||(e[4]=s('<p>A local account signs in with a username and password stored in Elevator, rather than through your institution&#39;s login. Open <strong>Admin</strong> › <strong>Instance Permissions (Classic)</strong>, click <strong>Create a local user</strong>, and fill in the form.</p><p><img src="'+h+'" alt="The classic Add/Edit a User form"></p><p>You can edit any local account you created.</p><ul><li><strong>SuperAdmin</strong> gives the account full control of every instance on this Elevator server, including creating new instances.</li><li><strong>Expires</strong> sets an expiration date for the account.</li></ul>',4))])}const _=r(m,[["render",v]]);export{C as __pageData,_ as default};
